POLICIES = [
    {"statements": [
        {"effect": "Allow", "actions": ["s3:GetObject", "s3:ListBucket"], "resources": ["finance-bucket/report.csv", "finance-bucket"]},
        {"effect": "Allow", "actions": ["s3:DeleteObject"], "resources": ["*"]},
    ]},
    {"statements": [
        {"effect": "Deny", "actions": ["s3:DeleteObject"], "resources": ["finance-bucket/report.csv"]},
    ]},
]

TESTS = [
    ("s3:GetObject", "finance-bucket/report.csv"),
    ("s3:DeleteObject", "finance-bucket/report.csv"),
    ("ec2:StartInstances", "i-0abc123"),
]

def evaluate(policies, action, resource):
    allowed = False
    for policy in policies:
        for stmt in policy.get("statements", []):
            action_match = "*" in stmt["actions"] or action in stmt["actions"]
            resource_match = "*" in stmt["resources"] or resource in stmt["resources"]
            if action_match and resource_match:
                if stmt["effect"] == "Deny":
                    return "DENY (explicit)"
                if stmt["effect"] == "Allow":
                    allowed = True
    return "ALLOW" if allowed else "DENY (implicit)"

for action, resource in TESTS:
    print(f"{action} on {resource} -> {evaluate(POLICIES, action, resource)}")
